head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDSTF07406.xml";
scwin.vCorpRegNo, scwin.vBzProcsNo = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var url = "/lstinvstg/KsqSkilValu.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=selectRetryYn&inputMessageId=SPECY_VALU_INOUT";
    url += "&CORP_REG_NO=" + scwin.vCorpRegNo; // 법인등록번호
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo; // 업무처리번호

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vCorpRegNo = parentWin.scwin.vCorpRegNo;
    scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    scwin.fn_list_sync();
};
